import sys, re

def main():
    if len(sys.argv) != 2:
        sys.exit(1)
    path = sys.argv[1]
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        sys.exit(1)
    required = ['## 决策结论', '## 选择方向', '## 不选方向', '## 依据与止损']
    for h in required:
        if h not in text:
            sys.exit(1)
    sections = {}
    for h in required:
        start = text.find(h)
        if start == -1:
            sys.exit(1)
        start += len(h)
        next_h = len(text)
        for other in required:
            if other == h:
                continue
            pos = text.find(other, start)
            if pos != -1 and pos < next_h:
                next_h = pos
        content = text[start:next_h].strip()
        if not content:
            sys.exit(1)
        sections[h] = content
    conclusion = sections['## 决策结论']
    if '做' not in conclusion and '不做' not in conclusion:
        sys.exit(1)
    if '做' in conclusion and '不做' in conclusion:
        pass
    direction = sections['## 选择方向']
    if not re.search(r'[-*]\s*\S+', direction) and not re.search(r'\d+\.\s*\S+', direction):
        sys.exit(1)
    not_direction = sections['## 不选方向']
    if not re.search(r'[-*]\s*\S+', not_direction) and not re.search(r'\d+\.\s*\S+', not_direction):
        sys.exit(1)
    basis = sections['## 依据与止损']
    if '依据' not in basis or '止损' not in basis:
        sys.exit(1)
    sys.exit(0)

if __name__ == '__main__':
    main()

