import sys, re

def main():
    if len(sys.argv) != 2:
        sys.exit(1)
    path = sys.argv[1]
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        sys.exit(1)
    # find Decision section
    m = re.search(r'^#+\s*Decision\s*$', text, re.MULTILINE | re.IGNORECASE)
    if not m:
        sys.exit(1)
    start = m.end()
    # find next heading or end
    next_heading = re.search(r'^#+\s', text[start:], re.MULTILINE)
    if next_heading:
        section = text[start:start+next_heading.start()]
    else:
        section = text[start:]
    content = section.strip().lower()
    if content not in ('yes', 'no'):
        sys.exit(1)
    if content == 'yes':
        if not re.search(r'^#+\s*Inner Loop\s*$', text, re.MULTILINE | re.IGNORECASE):
            sys.exit(1)
        if not re.search(r'^#+\s*Outer Loop\s*$', text, re.MULTILINE | re.IGNORECASE):
            sys.exit(1)
    sys.exit(0)

if __name__ == '__main__':
    main()

