        sys.exit(1)
    try:
        with open(sys.argv[1], 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        sys.exit(1)
    lower = text.lower()
    cost_keywords = ['成本', 'cost', '代价', '开销', '支出', '费用']
    benefit_keywords = ['收益', 'benefit', '好处', '回报', '利润', '优点']
    has_cost = any(kw in lower for kw in cost_keywords)
    has_benefit = any(kw in lower for kw in benefit_keywords)
    if not (has_cost and has_benefit):
        sys.exit(1)
    # 简单检查成本项和收益项下是否有具体条目（非空行或列表项）
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    cost_section = False
    benefit_section = False
    cost_items = 0
    benefit_items = 0
    for line in lines:
        low = line.lower()
        if any(kw in low for kw in cost_keywords):
            cost_section = True
            benefit_section = False
            continue
        if any(kw in low for kw in benefit_keywords):
            benefit_section = True
            cost_section = False
            continue
        if cost_section and (line.startswith('-') or line.startswith('*') or line[0].isdigit()):
            cost_items += 1
        if benefit_section and (line.startswith('-') or line.startswith('*') or line[0].isdigit()):
            benefit_items += 1
    if cost_items >= 1 and benefit_items >= 1:
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == '__main__':
    main()

