    # 查找表头行
    header_idx = None
    for i, line in enumerate(lines):
        if re.match(r'^\s*\|\s*token\s*\|\s*失败次数\s*\|\s*返工次数\s*\|\s*$', line):
            header_idx = i
            break
    if header_idx is None:
        sys.exit(1)
    # 检查分隔行
    if header_idx + 1 >= len(lines):
        sys.exit(1)
    sep_line = lines[header_idx + 1]
    if not re.match(r'^\s*\|\s*:?-+:?\s*\|\s*:?-+:?\s*\|\s*:?-+:?\s*\|\s*$', sep_line):
        sys.exit(1)
    # 检查至少一行数据
    data_rows = []
    for line in lines[header_idx + 2:]:
        if re.match(r'^\s*\|.*\|\s*$', line):
            data_rows.append(line)
        else:
            break
    if not data_rows:
        sys.exit(1)
    # 检查每行数据格式
    for row in data_rows:
        cells = [c.strip() for c in row.strip('|').split('|')]
        if len(cells) != 3:
            sys.exit(1)
        for cell in cells:
            if not re.match(r'^\d+$', cell):
                sys.exit(1)
    sys.exit(0)

