def main():
    if len(sys.argv) != 2:
        sys.exit(1)
    path = sys.argv[1]
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except Exception:
        sys.exit(1)
    # 检查是否包含恰好3个成员（简单启发：出现“成员”或“团队”后跟数字3，或列出三个名字）
    # 更可靠：要求文档中明确写出团队人数为3，或列出三个成员名字（用逗号/顿号分隔）
    # 这里采用宽松但可判定的方式：文档中必须出现“3人”或“三人”或“3个成员”或“三个成员”
    if not re.search(r'(3\s*人|三人|3\s*个成员|三个成员)', text):
        sys.exit(1)
    # 检查是否包含至少一个目标（O）和每个目标下至少2个关键结果（KR）
    # 简单启发：出现“O”或“目标”标记，且出现“KR”或“关键结果”标记至少2次
    # 更结构化：要求有“O1”或“目标1”等，且每个O后跟至少两个KR
    # 这里采用正则匹配：找到所有“O”或“目标”开头的行，然后检查每个O块内KR数量>=2
    lines = text.split('\n')
    o_indices = []
    for i, line in enumerate(lines):
        if re.match(r'^\s*(O\d*|目标\d*)[:：]', line, re.IGNORECASE):
            o_indices.append(i)
    if not o_indices:
        sys.exit(1)
    # 对每个O块，统计KR数量
    for idx, start in enumerate(o_indices):
        end = o_indices[idx+1] if idx+1 < len(o_indices) else len(lines)
        block = '\n'.join(lines[start:end])
        kr_count = len(re.findall(r'^\s*(KR\d*|关键结果\d*)[:：]', block, re.MULTILINE | re.IGNORECASE))
        if kr_count < 2:
            sys.exit(1)
    # 检查每个KR是否有验收口径：要求KR行或紧随其后的行包含“验收”或“口径”或“标准”或“判定”等词，或者包含可量化的数字+单位
    # 简化：要求整个文档中“验收”或“口径”或“标准”出现至少与KR数量相同的次数
    kr_total = len(re.findall(r'^\s*(KR\d*|关键结果\d*)[:：]', text, re.MULTILINE | re.IGNORECASE))
    if kr_total == 0:
        sys.exit(1)
    acceptance_terms = len(re.findall(r'(验收|口径|标准|判定|衡量)', text))
    if acceptance_terms < kr_total:
        sys.exit(1)
    # 检查一周时间范围：出现“一周”或“本周”或“7天”或“周”
    if not re.search(r'(一周|本周|7天|周)', text):
        sys.exit(1)
    sys.exit(0)

if __name__ == '__main__':
    main()

